import zipfile
import re
from xml.etree import ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/officeDocument/2006/math',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    's': 'http://schemas.openxmlformats.org/officeDocument/2006/sharedTypes',
    'x': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
}

def col_letter_to_index(letters):
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord('A') + 1)
    return idx - 1

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("Files in archive:")
for name in z.namelist():
    print(" ", name)

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rel_map = {}
for rel in rels:
    rel_map[rel.get('Id')] = rel.get('Target')

sheets = []
for sh in wb.find('x:sheets', NS):
    rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    name = sh.get('name')
    sheets.append((name, rel_map[rid].lstrip('/')))
print("\nSheets:", sheets)

shared_strings = []
try:
    ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in ss.findall('x:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared_strings.append(text)
except KeyError:
    pass

for sheet_name, sheet_path in sheets:
    print(f"\n--- Sheet: {sheet_name} ---")
    if not sheet_path.startswith('xl/'):
        sheet_path = 'xl/' + sheet_path
    root = ET.fromstring(z.read(sheet_path))
    data = root.find('x:sheetData', NS)
    for row in data.findall('x:row', NS):
        for c in row.findall('x:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('x:v', NS)
            if v is None or v.text is None:
                continue
            val = v.text
            if t == 's':
                val = shared_strings[int(val)]
            elif t == 'b':
                val = val == '1'
            elif t is None or t == 'n':
                try:
                    val = float(val)
                    if val.is_integer():
                        val = int(val)
                except ValueError:
                    pass
            print(f"  {ref}: {val!r}")

